let portraitDragMode=false,portraitDrag=null,portraitFocusId='';
function currentPortraitState(id=portraitFocusId){const state=KotobaCore.stageAt(project,scene(),Math.max(0,scene().blocks.findIndex(b=>b.id===selected)));if(!scene().multiPortrait)return state;const active=state.portraits.find(item=>item.character.id===id)||state.portraits.find(item=>item.character.id===block()?.speaker);return active?{...state,...active}:state}
function portraitEditTarget(state=currentPortraitState()){const b=block(),id=state.character?.id;if(!id||!state.portraitAsset||state.cg)return null;if(b?.speaker===id&&(b.type==='portrait'||b.type==='dialogue'&&!state.character.preserveStagePortrait))return b;const index=scene().blocks.findIndex(b=>b.id===selected),previous=scene().blocks.slice(0,index).findLast(x=>x.type==='portrait'&&x.speaker===id&&x.placementFor===b?.id);if(b&&previous?.type==='portrait'&&previous.speaker===id&&previous.placementFor===b.id)return previous;const target={id:uid(),type:'portrait',speaker:id,variant:state.portrait?.variant||'',position:'custom',visible:true,placementFor:b?.id||'',portraitLayout:KotobaCore.portraitPlacement(state.portrait,state.character),text:'调整立绘位置'};scene().blocks.splice(index<0?scene().blocks.length:index,0,target);return target}
function setPortraitPosition(values){const state=currentPortraitState();if(!state.portraitAsset||state.cg){notify(state.cg?'CG 显示期间请先隐藏 CG，再调整立绘':'当前画面没有可调整的立绘');return}change(()=>{const target=portraitEditTarget(state);target.portraitLayout=KotobaCore.portraitPlacement({position:'custom',portraitLayout:{...KotobaCore.portraitPlacement(state.portrait,state.character),...values}});target.position='custom'})}
const portraitEditor=editor,portraitInspector=drawInspector,portraitDrawStage=drawStage,portraitValidate=validateProject;
editor=function(){return portraitEditor().replace('<span class="micro">剧情编排</span>','<span class="micro">剧情编排</span><button class="btn small" data-action="portrait-drag">拖动立绘</button>')};
drawStage=function(force=false){stageRenderer.setMotionEnabled(!portraitDragMode||playing);portraitDrawStage(force);const stage=$('#stage');stage?.classList.toggle('portrait-drag-mode',portraitDragMode&&!playing);if(stage&&portraitDragMode&&!playing)stage.insertAdjacentHTML('beforeend','<span class="portrait-drag-hint">拖动立绘调整位置 · 位置从当前剧情开始生效</span>')};
drawInspector=function(){portraitInspector();if(view!=='script')return;const state=currentPortraitState();if(!state.portraitAsset||state.cg)return;const v=KotobaCore.portraitPlacement(state.portrait,state.character);$('#inspector')?.insertAdjacentHTML('beforeend',`<section class="portrait-settings"><h3>立绘位置 · ${esc(state.character.name)}</h3>${scene().multiPortrait?`<div class="field"><label>选择要调整的角色</label><select data-portrait-focus>${state.portraits.map(item=>`<option value="${esc(item.character.id)}" ${item.character.id===state.character.id?'selected':''}>${esc(item.character.name)}</option>`).join('')}</select></div>`:''}<div class="field-row">${[['x','水平位置（%）',0,100],['y','脚底位置（%）',0,150],['scale','立绘大小（%）',20,200]].map(([key,label,min,max])=>`<div class="field"><label>${label}</label><input type="number" min="${min}" max="${max}" step="0.1" data-portrait-layout="${key}" value="${Math.round(v[key]*10)/10}"></div>`).join('')}</div><div class="field-row"><div class="field"><label>位移动画时长（毫秒，0 为直接切换）</label><input type="number" min="0" max="5000" step="1" data-portrait-motion="moveDuration" value="${KotobaCore.portraitMotion(state.portrait).duration}"></div><div class="field"><label>移动方式</label><select data-portrait-motion="moveEasing">${optionList({'ease-in-out':'平滑起止',linear:'匀速','ease-in':'逐渐加速','ease-out':'逐渐减速'},KotobaCore.portraitMotion(state.portrait).easing)}</select></div></div><div class="card-actions"><button class="btn small ${portraitDragMode?'primary':''}" data-action="portrait-drag">${portraitDragMode?'结束拖动':'在画面中拖动'}</button><button class="btn small" data-action="portrait-reset">恢复居中</button></div><p class="field-note">调整当前可见角色，从当前剧情起生效。脚底 100% 为贴住画面底边；增大会下移。试演和导出保持相同比例。</p></section>`)};
validateProject=function(p){portraitValidate(p);for(const s of p.scenes)for(const b of s.blocks){if(b.moveDuration!==undefined&&(!Number.isFinite(b.moveDuration)||b.moveDuration<0||b.moveDuration>5000))throw Error('立绘位移时长必须在 0–5000 毫秒');if(b.moveEasing!==undefined&&!['linear','ease-in','ease-out','ease-in-out'].includes(b.moveEasing))throw Error('立绘移动方式无效')}for(const value of [...p.characters,...p.scenes.flatMap(s=>s.blocks)])if(value.portraitLayout){const v=value.portraitLayout;for(const [key,min,max]of [['x',0,100],['y',0,150],['scale',20,200]])if(typeof v[key]!=='number'||!Number.isFinite(v[key])||v[key]<min||v[key]>max)throw Error('立绘位置或大小超出范围')}return p};
document.addEventListener('change',e=>{if(e.target.dataset.portraitMotion){const state=currentPortraitState();if(!state.portraitAsset||state.cg)return;change(()=>{const target=portraitEditTarget(state);target[e.target.dataset.portraitMotion]=e.target.dataset.portraitMotion==='moveDuration'?KotobaCore.portraitMotion({moveDuration:e.target.value}).duration:e.target.value});return}if(e.target.hasAttribute('data-portrait-focus')){portraitFocusId=e.target.value;drawInspector();return}if(e.target.dataset.portraitLayout){const value=Number(e.target.value);if(Number.isFinite(value))setPortraitPosition({[e.target.dataset.portraitLayout]:value})}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]'),action=button?.dataset.action;if(['portrait-drag','portrait-reset'].includes(action)){e.preventDefault();e.stopImmediatePropagation();if(action==='portrait-reset'){setPortraitPosition({x:50,y:100,scale:100});return}if(!portraitDragMode){const state=currentPortraitState();if(!state.portraitAsset||state.cg){notify(state.cg?'请先隐藏 CG，再调整立绘':'请先为画面中的角色设置立绘');return}}portraitDragMode=!portraitDragMode;subtitleDragMode=false;draw();return}if(portraitDragMode&&!playing&&e.target.closest('#stage')){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('pointerdown',e=>{if(!portraitDragMode||playing||e.button!==0||!e.target.closest('#stage .stage-character'))return;e.preventDefault();e.stopImmediatePropagation();const stage=$('#stage'),image=e.target.closest('.stage-character'),state=currentPortraitState(image.dataset.characterId);portraitFocusId=state.character?.id||'';image.getAnimations().forEach(animation=>animation.cancel());if(!state.portraitAsset||state.cg)return;snapshot();const target=portraitEditTarget(state),layout=KotobaCore.portraitPlacement(state.portrait,state.character);target.position='custom';target.portraitLayout={...layout};portraitDrag={pointerId:e.pointerId,stage,image,target,layout,rect:stage.getBoundingClientRect(),x:e.clientX,y:e.clientY};if(e.isTrusted)stage.setPointerCapture(e.pointerId)},true);
document.addEventListener('pointermove',e=>{const d=portraitDrag;if(!d||d.pointerId!==e.pointerId)return;e.preventDefault();const layout=KotobaCore.portraitPlacement({position:'custom',portraitLayout:{...d.layout,x:d.layout.x+(e.clientX-d.x)/d.rect.width*100,y:d.layout.y+(e.clientY-d.y)/d.rect.height*100}});d.target.portraitLayout=layout;d.image.style.left=layout.x+'%';d.image.style.bottom=(100-layout.y)+'%';for(const key of ['x','y']){const field=$('[data-portrait-layout="'+key+'"]');if(field)field.value=Math.round(layout[key]*10)/10}},true);
function finishPortraitDrag(e){const d=portraitDrag;if(!d||d.pointerId!==e.pointerId)return;portraitDrag=null;if(d.stage.hasPointerCapture(e.pointerId))d.stage.releasePointerCapture(e.pointerId);save();draw()}
document.addEventListener('pointerup',finishPortraitDrag,true);document.addEventListener('pointercancel',finishPortraitDrag,true);
draw();
